from solution import larg_nnum


def test_module_imports():
    assert solution is not None


def test_example():
    assert larg_nnum([10, 20, 50, 70, 90, 20, 50, 40, 60, 80, 100], 2) == [100, 90]


def test_descending_order():
    assert larg_nnum([3, 1, 4, 1, 5, 9, 2], 3) == [9, 5, 4]
    assert larg_nnum([5, 4, 3, 2, 1], 3) == [5, 4, 3]


def test_n_zero_and_negative():
    assert larg_nnum([1, 2, 3], 0) == []
    assert larg_nnum([1, 2, 3], -1) == []


def test_n_greater_than_length():
    assert larg_nnum([2, 1, 3], 5) == [3, 2, 1]
    assert larg_nnum([2, 1, 3], 3) == [3, 2, 1]


def test_empty_list():
    assert larg_nnum([], 2) == []
    assert larg_nnum([], 0) == []


def test_duplicates_preserved():
    assert larg_nnum([50, 20, 50, 40], 3) == [50, 50, 40]


def test_negative_and_float_numbers():
    assert larg_nnum([-5, -1, -10, 0], 2) == [0, -1]
    assert larg_nnum([1.5, 2.75, 0.5], 2) == [2.75, 1.5]


def test_does_not_mutate_input():
    data = [10, 20, 50, 70]
